// Extract the applicant profile JSON from the Intake Agent's output
const intakeOutput = $input.first().json.output || '';

let profile = null;
try {
  const jsonMatch = intakeOutput.match(/```json([\s\S]*?)```/);
  if (jsonMatch) {
    profile = JSON.parse(jsonMatch[1].trim());
  }
} catch (e) {
  // Profile not yet complete — continue conversation
}

return [{
  json: {
    intake_output: intakeOutput,
    profile: profile,
    profile_complete: profile?.profile_complete === true
  }
}];

