const researchOutput = $input.first().json.text || '';
const profile = $('Load Visa Requirements').first().json.profile;
const requirements = $('Load Visa Requirements').first().json.requirements;

let supplementaryData = {};
try {
  const jsonMatch = researchOutput.match(/```json([\s\S]*?)```/);
  const jsonStr = jsonMatch ? jsonMatch[1].trim() : researchOutput.trim();
  supplementaryData = JSON.parse(jsonStr);
} catch (e) {
  supplementaryData = { practical_tips: [researchOutput] };
}

return [{
  json: {
    profile: profile,
    requirements: requirements,
    supplementary: supplementaryData
  }
}];

parameters.text:
=You are a senior visa consultant producing a clear, actionable visa requirements report.

Applicant:
- Nationality: {{ $json.profile.nationality }}
- Residence: {{ $json.profile.country_of_residence }}
- Destination: {{ $json.profile.destination_country }}
- Purpose: {{ $json.profile.purpose_of_visit }}
- Schengen Main Country: {{ $json.profile.schengen_main_country || 'N/A' }}
- Visa Type: {{ $json.requirements.visa_type }}

Supplementary Research:
{{ JSON.stringify($json.supplementary, null, 2) }}

Produce a concise executive summary (3–4 sentences) and embassy guidance if applicable.

Respond in JSON format:
{
  "executive_summary": "...",
  "embassy_guidance": "...",
  "eta_eligible": false,
  "eta_note": null,
  "priority_flags": ["..."]
}

