// Assemble the final visa requirements report as Markdown
const analysisOutput = $input.first().json.text || '';
const profile = $('Parse Research Output').first().json.profile;
const requirements = $('Parse Research Output').first().json.requirements;
const supplementary = $('Parse Research Output').first().json.supplementary;

let analysis = {};
try {
  const jsonMatch = analysisOutput.match(/```json([\s\S]*?)```/);
  const jsonStr = jsonMatch ? jsonMatch[1].trim() : analysisOutput.trim();
  analysis = JSON.parse(jsonStr);
} catch (e) {
  analysis = { executive_summary: analysisOutput };
}

// Build Markdown report
const mandatoryDocs = requirements.required_documents.filter(d => d.mandatory);
const optionalDocs = requirements.required_documents.filter(d => !d.mandatory);

let report = `# ${requirements.visa_type} — Requirements Report\n\n`;
report += `**Applicant:** ${profile.nationality} national, residing in ${profile.country_of_residence}\n`;
report += `**Destination:** ${profile.destination_country}${profile.schengen_main_country ? ` (${profile.schengen_main_country})` : ''}\n`;
report += `**Purpose:** ${profile.purpose_of_visit}\n\n`;
report += `---\n\n`;

if (analysis.executive_summary) {
  report += `## Summary\n${analysis.executive_summary}\n\n`;
}

if (analysis.embassy_guidance) {
  report += `## 🏛️ Embassy Selection\n${analysis.embassy_guidance}\n\n`;
}

report += `## Visa Details\n`;
report += `- **Fee:** ${requirements.fee}\n`;
report += `- **Processing Time:** ${requirements.processing_time}\n`;
report += `- **Maximum Stay:** ${requirements.max_stay}\n`;
report += `- **Apply Online:** ${requirements.apply_url}\n\n`;

report += `## ✅ Required Documents\n`;
mandatoryDocs.forEach(doc => {
  report += `- **${doc.document}:** ${doc.details}\n`;
});

if (optionalDocs.length > 0) {
  report += `\n## ⭐ Recommended Documents\n`;
  optionalDocs.forEach(doc => {
    report += `- **${doc.document}:** ${doc.details}\n`;
  });
}

report += `\n## 📋 Application Steps\n`;
requirements.application_steps.forEach((step, i) => {
  report += `${i + 1}. ${step}\n`;
});

if (supplementary.nationality_specific_notes?.length) {
  report += `\n## 🔍 Nationality-Specific Notes\n`;
  supplementary.nationality_specific_notes.forEach(n => { report += `- ${n}\n`; });
}

if (supplementary.situation_flags?.length) {
  report += `\n## ⚠️ Important Flags\n`;
  supplementary.situation_flags.forEach(f => { report += `- ${f}\n`; });
}

if (supplementary.practical_tips?.length) {
  report += `\n## 💡 Practical Tips\n`;
  supplementary.practical_tips.forEach(t => { report += `- ${t}\n`; });
}

report += `\n## ⚠️ Key Notes\n`;
requirements.key_notes.forEach(note => { report += `- ${note}\n`; });

report += `\n## 🔗 Official Sources\n`;
const sources = [
  { title: `Official ${requirements.visa_type} Information`, url: requirements.info_url },
  { title: 'Apply Online', url: requirements.apply_url },
  ...Object.entries(requirements.vac_providers || {}).map(([name, url]) => ({ title: `VAC — ${name}`, url }))
];
sources.forEach(s => { if (s.url) report += `- [${s.title}](${s.url})\n`; });

if (supplementary.recommended_sources?.length) {
  supplementary.recommended_sources.forEach(s => { report += `- [${s.title}](${s.url})\n`; });
}

report += `\n---\n*Generated by Visa Application Multi-Agent System — Phase 1 (n8n)*`;

return [{
  json: {
    report_markdown: report,
    visa_type: requirements.visa_type,
    applicant_nationality: profile.nationality,
    destination: profile.destination_country,
    executive_summary: analysis.executive_summary || '',
    embassy_guidance: analysis.embassy_guidance || null,
    priority_flags: analysis.priority_flags || []
  }
}];
